package com.deruy.plugin.contract;import org.bukkit.command.*;import org.bukkit.entity.Player;import java.util.*;
public final class ContractCommand implements TabExecutor{private final ContractManager m;public ContractCommand(ContractManager m){this.m=m;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player p)){s.sendMessage("§c플레이어만 사용할 수 있습니다.");return true;}if(!s.hasPermission("deruy.contract.use")){s.sendMessage("§c권한이 없습니다.");return true;}String sub=a.length==0?"list":a[0].toLowerCase();switch(sub){case"list"->s.sendMessage("§4위험 계약: §e"+String.join(", ",m.ids()));case"accept"->{if(a.length<2||!m.accept(p,a[1]))s.sendMessage("§c계약을 찾을 수 없거나 이미 진행 중입니다.");}case"status"->s.sendMessage("§e"+m.status(p));case"cancel"->{m.cancel(p);s.sendMessage("§7계약을 취소했습니다.");}default->s.sendMessage("§e/contract list|accept <계약>|status|cancel");}return true;}public List<String> onTabComplete(CommandSender s,Command c,String l,String[]a){if(a.length==1)return List.of("list","accept","status","cancel").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();if(a.length==2&&a[0].equalsIgnoreCase("accept"))return m.ids().stream().filter(x->x.startsWith(a[1])).toList();return List.of();}}
